(() => {'use strict';
const g=()=>window.gameDebug,labels={sword:'Меч',staff:'Посох',shield:'Щит',torch:'Факел',bow:'Лук',empty:'Свободно'};
function label(item,a=g()?.active()){return item==='staff'&&a?.classId==='cleric'?'Булава':labels[item];}
function ensure(){const game=g();if(!game)return;const s=game.state;s.lightFixtures||={};for(const a of s.party){if(!a.hands){a.hands=a.kind===2?['sword','shield']:a.kind===1?['staff','empty']:a.weapon==='bow'?['bow','bow']:['sword','empty'];a.torches=0;a.torch=false;a.armorAC=a.kind===2?a.ac-2:a.ac;}a.torches=Math.max(0,a.torches||0);if(!a.torches||!a.hands.includes('torch'))a.torch=false;shieldAC(a);}}
function fixture(id,scene=g().state.scene){return g().state.lightFixtures[scene+':'+id]||{present:true,lit:true};}
function setFixture(id,value){g().state.lightFixtures[g().state.scene+':'+id]=value;}
function guard(bonus=false){const game=g(),a=game.active();return !game.busy&&a.hp>0&&!a.dead&&(!game.state.combat||!(bonus?a.bonusUsed:a.acted));}
function spend(bonus=false){if(g().state.combat)g().active()[bonus?'bonusUsed':'acted']=true;}
function refresh(message){if(message)g().tell(message);g().save();g().render();}
function shieldAC(a){if(a.kind===2||a.classId)a.ac=a.armorAC+(a.hands.includes('shield')?2:0);}
function equip(hands){ensure();const a=g().active();if(!guard())return;if(a.classId&&hands.some(x=>x==='bow'&&a.classId!=='rogue'||x==='shield'&&a.classId!=='fighter'))return;if(hands.includes('torch')&&!a.torches){refresh('Сначала найдите факел и снимите его с настенного крепления.');return;}if(hands.length!==2||hands.includes('bow')&&hands.some(x=>x!=='bow'))return;if(a.classId&&hands.some(hand=>!['empty','torch'].includes(hand)&&!a.inventory.some(name=>InventoryRules.handType(name)===hand))){refresh('Этого предмета больше нет в вашем снаряжении.');return;}if(InventoryRules.slotsUsed({...a,hands},g().state)>20){refresh('Освободите ячейку, чтобы убрать предмет из рук.');return;}const before=a.hands.join(','),stowed=a.torch&&!hands.includes('torch');a.hands=[...hands];if(!hands.includes('torch'))a.torch=false;if(a.kind===0)a.weapon=hands.includes('bow')?'bow':'sword';shieldAC(a);spend();if(before!==a.hands.join(','))window.dispatchEvent(new CustomEvent('game-action',{detail:{type:'equipment',success:true,kind:'hands'}}));refresh(a.name+': '+hands.map(x=>label(x,a)).join(' + ')+(stowed?'. Факел погашен и убран в рюкзак.':'.'));}
function presets(a){if(a.classId==='rogue')return [['Меч + свободная рука',['sword','empty']],['Меч + факел',['sword','torch']]];if(a.classId==='cleric')return [['Булава + свободная рука',['staff','empty']],['Булава + факел',['staff','torch']],['Свободные руки',['empty','empty']]];return a.kind===2?[['Меч + щит',['sword','shield']],['Меч + факел',['sword','torch']],['Щит + факел',['shield','torch']],['Меч + свободная рука',['sword','empty']]]:a.kind===0?[['Меч + свободная рука',['sword','empty']],['Меч + факел',['sword','torch']],['Лук · две руки',['bow','bow']]]:[['Посох + свободная рука',['staff','empty']],['Посох + факел',['staff','torch']],['Факел + свободная рука',['empty','torch']],['Свободные руки',['empty','empty']]];}
function button(label,fn,disabled=false){const b=document.createElement('button');b.textContent=label;b.onclick=fn;b.disabled=disabled;return b;}
function fillHands(panel){ensure();const a=g().active();panel.replaceChildren();const title=document.createElement('p');title.className='hand-summary';title.textContent='Руки: '+a.hands.map(x=>label(x,a)).join(' + ')+' · Защита '+a.ac;panel.append(title);for(const [label,hands]of presets(a)){const b=button(label,()=>{equip(hands);fillHands(panel);},!guard()||hands.includes('torch')&&!a.torches);b.className='hand-choice'+(hands.join()===a.hands.join()?' equipped':'');panel.append(b);}const note=document.createElement('p');note.className='subtle';note.textContent='Лук требует две руки. Щит даёт +2 КД. Факел в руке даёт помеху атакам — правило этой игры. В бою смена снаряжения расходует действие.';panel.append(note);}
function openHands(){ensure();const d=document.getElementById('modal');document.getElementById('modal-title').textContent='Что держать в руках';const p=document.getElementById('modal-body');fillHands(p);d.showModal();}
function toggle(){ensure();const a=g().active();if(!guard(true))return;if(!a.torches||!a.hands.includes('torch')){refresh('Факела в руке нет. Возьмите найденный факел через «Снаряжение рук».');return;}a.torch=!a.torch;spend(true);refresh(a.name+(a.torch?' зажигает факел.':' гасит факел.'));}
function stow(){ensure();if(!guard(true))return;const a=g().active();if(!a.hands.includes('torch'))return;if(InventoryRules.slotsUsed({...a,hands:a.hands.map(x=>x==='torch'?'empty':x)},g().state)>20){refresh('Освободите ячейку для факела.');return;}a.torch=false;a.hands=a.hands.map(x=>x==='torch'?'empty':x);shieldAC(a);spend(true);refresh(a.name+' гасит факел и убирает его в рюкзак.');}
function interact(p){ensure();const game=g(),a=game.active(),f=fixture(p.id);if(!guard(true)||Math.abs(a.x-p.x)+Math.abs(a.y-p.y)!==1)return;const d=document.getElementById('modal');document.getElementById('modal-title').textContent=f.present?'Настенный факел':'Пустое крепление';const body=document.getElementById('modal-body');body.replaceChildren();const note=document.createElement('p');note.textContent=f.present?'Снимите факел: он занимает одну руку. Если руки заняты, факел будет погашен и убран в рюкзак.':'Здесь можно оставить факел. Горящий факел продолжит освещать комнату.';body.append(note);
 const close=()=>d.close();if(f.present)body.append(button('Снять и взять факел',()=>{if(!guard(true)||!fixture(p.id).present)return;const slot=a.hands.indexOf('empty');if(slot<0&&!window.Inventory.roomFor('torch')){close();window.openObjectDialogue({name:'Рюкзак заполнен',description:'Освободите ячейку или руку для факела.'});return;}a.torches++;if(slot>=0){a.hands[slot]='torch';a.torch=f.lit;}setFixture(p.id,{present:false,lit:false});spend(true);close();refresh(a.name+(slot>=0?' берёт факел в свободную руку.':' гасит снятый факел и кладёт его в рюкзак.'));}));else body.append(button('Оставить факел на стене',()=>{if(!guard(true)||fixture(p.id).present||a.torches<1)return;const held=a.hands.includes('torch'),lit=held&&a.torch;a.torches--;if(held){a.hands=a.hands.map(x=>x==='torch'?'empty':x);a.torch=false;}setFixture(p.id,{present:true,lit});shieldAC(a);spend(true);close();refresh(lit?'Горящий факел оставлен на стене.':'Погашенный факел закреплён на стене.');},a.torches<1));if(f.present)body.append(button(f.lit?'Погасить на стене':'Зажечь на стене',()=>{if(!guard(true)||!fixture(p.id).present)return;setFixture(p.id,{present:true,lit:!f.lit});spend(true);close();refresh(f.lit?'Настенный факел погашен.':'Настенный факел зажжён.');}));d.showModal();}
function canAttack(a){if(!a.hands)return true;if(a.classId==='cleric')return a.hands.includes('staff')||a.hands.includes('empty');if(a.kind===1)return a.hands.includes('empty');return a.hands.includes('sword')||a.hands[0]==='bow'&&a.hands[1]==='bow';}
function lightSources(){ensure();const game=g();return game.scene.lights.filter(l=>!(game.state.trial&&game.state.scene==='hub'&&l.kind==='chandelier'&&l.x>12)&&(l.kind!=='wall'||fixture(l.fixtureId).present&&fixture(l.fixtureId).lit));}
function inventory(panel){ensure();const a=g().active();panel.append(button('Снаряжение рук',openHands),button(a.torch?'Погасить факел':'Зажечь факел',toggle,!guard(true)||!a.torches||!a.hands.includes('torch')),button('Погасить и убрать',stow,!guard(true)||!a.hands.includes('torch')));}
window.Torches={label,ensure,fixture,equip,fillHands,openHands,interact,toggle,stow,canAttack,lightSources,inventory,labels};
})();
